INSERT IGNORE INTO `site_word` (`name`, `lang`, `txt`) VALUES ('c2 Standards hint', 'kz', 'Сеттің толық себесі = тағамдар себесі + {over} тг (айлық, аренда, к.у., доставка, реклама). Ұсынылатын баға = толық себес + {mk}%, сосын 490 / 990-ға дейін дөңгелектенеді.'), ('c2 Standards hint', 'ru', 'Полная себестоимость сета = себестоимость блюд + {over} тг (зарплата, аренда, коммуналка, доставка, реклама). Рекомендуемая цена = полная себестоимость + {mk}%, затем округляется до 490 / 990.'), ('c2 Standards hint', 'en', 'Full set cost = dishes cost + {over} KZT (salary, rent, utilities, delivery, ads). Suggested price = full cost + {mk}%, then rounded up to 490 / 990.'), ('c2 Standards hint', 'uz', 'Setning to''liq tannarxi = taomlar tannarxi + {over} tg (oylik, ijara, kommunal, yetkazib berish, reklama). Tavsiya etilgan narx = to''liq tannarx + {mk}%, so''ng 490 / 990 gacha yaxlitlanadi.'), ('c2 Standards hint', 'ky', 'Сеттин толук өздүк наркы = тамактардын өздүк наркы + {over} тг (айлык, ижара, коммуналдык, жеткирүү, жарнама). Сунушталган баа = толук өздүк нарк + {mk}%, андан кийин 490 / 990го чейин тегеректелет.');
