INSERT IGNORE INTO `site_word` (`name`, `lang`, `txt`) VALUES ('c2 Fact source', 'kz', 'Факт: {period}, {orders} тапсырыс, {days} күн. Тапсырыс саны мен сатылым — сатылымдардан (бас тартылғандарсыз), шығындар — ОПиУ-дан, доставка — курьер жалақысы. ÷ тапсырыс саны.'), ('c2 Fact source', 'ru', 'Факт: {period}, {orders} заказов, {days} дн. Заказы и продажи — из продаж (без отменённых), расходы — из ОПиУ, доставка — зарплата курьеров. ÷ число заказов.'), ('c2 Fact source', 'en', 'Actual: {period}, {orders} orders, {days} days. Orders and sales come from sales (without cancelled), costs from the P&L, delivery from courier pay. ÷ number of orders.'), ('c2 Fact source', 'uz', 'Fakt: {period}, {orders} buyurtma, {days} kun. Buyurtmalar va sotuv — sotuvlardan (bekor qilinganlarsiz), xarajatlar — OPiU dan, yetkazib berish — kuryer maoshi. ÷ buyurtmalar soni.'), ('c2 Fact source', 'ky', 'Факт: {period}, {orders} заказ, {days} күн. Заказдар жана сатуу — сатуулардан (жокко чыгарылгандарсыз), чыгымдар — ОПиУдан, жеткирүү — курьерлердин айлыгы. ÷ заказ саны.');
INSERT IGNORE INTO `site_word` (`name`, `lang`, `txt`) VALUES ('c2 Fact gray', 'kz', 'Сұр мәндер — ОПиУ-да бұл кезеңге шығын жазылмаған (не тапсырыс жоқ), сондықтан жоспар мәні алынды. Пайда сатылған сетте нақты орташа сату бағасымен, сатылмағанында қазіргі бағамен.'), ('c2 Fact gray', 'ru', 'Серые значения — в ОПиУ за этот период расход не внесён (или нет заказов), поэтому взято плановое значение. Прибыль проданного сета считается по фактической средней цене продажи, непроданного — по текущей цене.'), ('c2 Fact gray', 'en', 'Grey values have no cost entered in the P&L for this period (or no orders), so the plan value is used. Profit for a sold set uses its actual average sale price, otherwise the current price.'), ('c2 Fact gray', 'uz', 'Kulrang qiymatlar — OPiU da bu davr uchun xarajat kiritilmagan (yoki buyurtma yo''q), shuning uchun reja qiymati olindi. Sotilgan set foydasi haqiqiy o''rtacha sotuv narxi bilan, sotilmagani joriy narx bilan hisoblanadi.'), ('c2 Fact gray', 'ky', 'Боз маанилер — ОПиУда бул мезгилге чыгым жазылган эмес (же заказ жок), ошондуктан план мааниси алынды. Сатылган сеттин пайдасы чыныгы орточо сатуу баасы менен, сатылбаганы учурдагы баа менен эсептелет.');
INSERT IGNORE INTO `site_word` (`name`, `lang`, `txt`) VALUES ('c2 Fact empty', 'kz', 'Факт әлі толтырылмаған: есеп План мәндерімен жүреді. Нақты мәндерді жазып, «Сақтау» басыңыз.'), ('c2 Fact empty', 'ru', 'Факт ещё не заполнен: расчёт идёт по Плану. Впишите фактические значения и нажмите «Сохранить».'), ('c2 Fact empty', 'en', 'Actual values are not filled yet: the calculation uses the Plan. Enter actual values and press Save.'), ('c2 Fact empty', 'uz', 'Fakt hali to''ldirilmagan: hisob Reja qiymatlari bilan. Haqiqiy qiymatlarni yozib, «Saqlash» ni bosing.'), ('c2 Fact empty', 'ky', 'Факт азырынча толтурулган жок: эсеп План маанилери менен жүрөт. Чыныгы маанилерди жазып, «Сактоо» басыңыз.');
INSERT IGNORE INTO `site_word` (`name`, `lang`, `txt`) VALUES ('c2 Fact manual', 'kz', 'Факт мәндері қолмен толтырылады, План өзгермейді. Бос өріс — План мәні (сұр).'), ('c2 Fact manual', 'ru', 'Фактические значения вводятся вручную, План не меняется. Пустое поле — значение Плана (серое).'), ('c2 Fact manual', 'en', 'Actual values are entered manually, the Plan stays as is. An empty field uses the Plan value (grey).'), ('c2 Fact manual', 'uz', 'Fakt qiymatlari qo''lda kiritiladi, Reja o''zgarmaydi. Bo''sh maydon — Reja qiymati (kulrang).'), ('c2 Fact manual', 'ky', 'Факт маанилери кол менен толтурулат, План өзгөрбөйт. Бош талаа — План мааниси (боз).');
INSERT IGNORE INTO `site_word` (`name`, `lang`, `txt`) VALUES ('c2 Fill from last month', 'kz', 'Соңғы айдың нақты деректерімен толтыру'), ('c2 Fill from last month', 'ru', 'Заполнить по данным прошлого месяца'), ('c2 Fill from last month', 'en', 'Fill from last month''s data'), ('c2 Fill from last month', 'uz', 'O''tgan oy ma''lumotlari bilan to''ldirish'), ('c2 Fill from last month', 'ky', 'Акыркы айдын маалыматтары менен толтуруу');
INSERT IGNORE INTO `site_word` (`name`, `lang`, `txt`) VALUES ('c2 Filled from month', 'kz', 'Толтырылды: {m}, {o} тапсырыс. Тексеріп, «Сақтау» басыңыз.'), ('c2 Filled from month', 'ru', 'Заполнено: {m}, {o} заказов. Проверьте и нажмите «Сохранить».'), ('c2 Filled from month', 'en', 'Filled: {m}, {o} orders. Check and press Save.'), ('c2 Filled from month', 'uz', 'To''ldirildi: {m}, {o} buyurtma. Tekshirib, «Saqlash» ni bosing.'), ('c2 Filled from month', 'ky', 'Толтурулду: {m}, {o} заказ. Текшерип, «Сактоо» басыңыз.');
